 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    vertical_tracks = []
    two_centers = []

    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == 1:
                # A short rightward stroke ending in a raised 1.
                for dc in (1, 2):
                    if 0 <= c + dc < w:
                        out[r][c + dc] = 5
                if r - 1 >= 0 and c + 2 < w:
                    out[r - 1][c + 2] = 1
            elif color == 2:
                # A five-cell bar, centered two cells to the left.
                for dc in (1, 3):
                    if 0 <= c - dc < w:
                        out[r][c - dc] = 5
                if 0 <= c - 2 < w:
                    out[r][c - 2] = 4
                if c - 4 >= 0:
                    out[r][c - 4] = 2
                two_centers.append((r, c - 2))
            elif color == 3:
                # Extend three cells downward.
                for dr in (1, 2):
                    if r + dr < h:
                        out[r + dr][c] = 5
                if r + 3 < h:
                    out[r + 3][c] = 3
                vertical_tracks.append((c, r, min(h - 1, r + 3)))
            elif color == 6:
                # Extend six cells upward.
                for dr in range(1, 6):
                    if r - dr >= 0:
                        out[r - dr][c] = 5
                if r - 6 >= 0:
                    out[r - 6][c] = 6
                vertical_tracks.append((c, max(0, r - 6), r))

    # Where a downward/upward stroke passes through the 2-bar's center,
    # continue the crossing as a diagonal 4 trail to the lower-left edge.
    for rr, cc in two_centers:
        if not (0 <= rr < h and 0 <= cc < w):
            continue
        if any(col == cc and lo <= rr <= hi for col, lo, hi in vertical_tracks):
            for k in range(min(h - 1 - rr, cc) + 1):
                out[rr + k][cc - k] = 4
    return out
